import logo from "./images/newlogo2.png";
import "./App.css";
import { Routes, Route, Link, useLocation } from "react-router-dom";
import { useEffect } from "react";

import Quiz from "./Quiz";
import Quizstart from "./Quizstart";

function App() {

  const location = useLocation();

  useEffect(() => {

    if (location.pathname !== "/") return;

    const starsContainer = document.getElementById("stars");

    if (!starsContainer) return;

    starsContainer.innerHTML = "";

    for (let i = 0; i < 180; i++) {

      const star = document.createElement("div");

      const size =
        Math.random() > 0.96
          ? "lg"
          : Math.random() > 0.7
          ? "md"
          : "sm";

      star.className = `star ${size}`;

      star.style.left = Math.random() * 100 + "%";
      star.style.top = Math.random() * 100 + "%";

      star.style.animationDuration =
        2 + Math.random() * 6 + "s";

      star.style.animationDelay =
        Math.random() * 5 + "s";

      starsContainer.appendChild(star);
    }

  }, [location.pathname]);

  return (
    <Routes>

      <Route
        path="/"
        element={
          <>
            <div className="stars" id="stars"></div>

            <div className="App">
              <header className="container App-header text-white d-flex flex-column align-items-center justify-content-center my-5 pt-5">

                <span className="live-badge d-flex align-items-center fw-semibold">
                  Live-AI Quiz Platform
                </span>

                <img src={logo} className="App-logo" alt="logo" />

                <h1 className="fw-normal text-white">
                  Welcome To Our{" "}
                  <span className="fw-bold gradient-text">
                    Quiz Board
                  </span>
                </h1>

                <Link
                  to="/instructions"
                  className="createbtn"
                >
                  Create Quiz
                </Link>

              </header>
            </div>
          </>
        }
      />

      <Route path="/instructions" element={<Quiz />} />
      <Route path="/quiz" element={<Quizstart />} />

    </Routes>
  );
}

export default App;
